tasks.source:
type Task = {
  title:string
  priority:int = 2
  notes?:string
}

let root(): Task+ = {
  <Task title="Ship the site" priority=1 />
  <Task title="Plan the next release, and then write down every step of it for the whole team" notes="After the site ships" />
}

uitext.source:
// A note for whoever reads the source.
type uitext = string
type WebUIText = uitext
type Choice = { value:string label:uitext hint?:WebUIText note:uitext = "Fine" }
external component <Text tone:string = "plain" content text:uitext />
let greet(name:string): uitext = { "Hello, " + name }
let root() = {
  <Choice value="a" label="First choice" hint="Pick me" />
  <Text>Shown to people</Text>
  <Choice value="b" label={"Second " + "choice"} />
}

elementIds.source:
import "@nx/viewer"

type Step = { id:string title:string }
type Choice = { value:string label:string }

viewer Step = <ElementViewer title=title id=id />
viewer Choice = <ElementViewer title=label id=value idPosition=end />

let steps = {
  <Step
    id="welcome"
    title="Welcome"
  />
  <Choice value="yes" label="Yes" />
}

icons.source:
import "@nx/viewer"

type Choice = { value:string label:string }
type Note = { text:string }
type Tip = { text:string }
type Status =
  | open
  | closed { reason:string }

viewer Choice = <ElementViewer title=label icon="circle-dot" />
viewer Tip = <ElementViewer icon="no-such-icon" />

let items = {
  <Choice value="a" label="First" />
  <Note text="Plain" />
  <Tip text="Unknown icon" />
  <Status.closed reason="done" />
}

let held = <Note text="Inline" />

let picks:Choice+ = {
  <Choice value="b" label="Second" />
}

